(()=>{const ribbon=document.querySelector('.ribbon-moving'),button=ribbon?.querySelector('.ribbon-toggle');if(!button)return;button.addEventListener('click',()=>{const paused=ribbon.classList.toggle('is-paused');button.setAttribute('aria-pressed',String(paused));button.setAttribute('aria-label',paused?'Retomar animação da faixa':'Pausar animação da faixa');button.textContent=paused?'Retomar':'Pausar';});const observer=new IntersectionObserver(([entry])=>ribbon.classList.toggle('is-offscreen',!entry.isIntersecting));observer.observe(ribbon);})();
